INSERT INTO kn_posts (
  lang, slug, title, excerpt, content, status, published_at,
  category_id, featured_image, meta_title, meta_description, og_image,
  created_at, updated_at
) VALUES (
  'fr',
  'trophee-independant-orange-2024',
  'Keepnew, finaliste du Trophée de l’Indépendant Orange 2024',
  'Sur plus de 850 entreprises candidates à l’échelle nationale, Keepnew figure parmi les 10 finalistes du Trophée de l’Indépendant Orange 2024. Retour sur une reconnaissance qui nous engage pour la suite.',
  '[{"type":"heading","level":"h2","text":"850 candidatures, 10 finalistes : une sélection à l’échelle nationale"},{"type":"text","text":"<p>Le Trophée de l’Indépendant, organisé par Orange Belgique, met chaque année à l’honneur les entrepreneurs indépendants du pays — ceux qui, souvent seuls ou en petite équipe, portent un projet au quotidien avec exigence et régularité. En 2024, plus de <strong>850 entreprises</strong> ont déposé leur candidature à travers la Belgique.</p><p>Sur ce volume de candidatures, Keepnew a été sélectionné parmi les <strong>10 finalistes</strong> du concours. Pas un premier prix, mais une sélection à ce niveau, sur un bassin national aussi large, est déjà une reconnaissance que nous n’attendions pas nécessairement — et qui nous touche particulièrement, parce qu’elle vient saluer un travail de terrain, pas une campagne de communication.</p>"},{"type":"heading","level":"h2","text":"Une reconnaissance qui parle de qui nous sommes"},{"type":"text","text":"<p>Keepnew est une entreprise familiale liégeoise, fondée par <strong>Mathieu et Antoine Forêt</strong>. Pas de siège social lointain, pas de franchise : une équipe qui se déplace chaque semaine chez des centaines de familles en province de Liège, à Namur, à Bruxelles et dans le Luxembourg belge, pour redonner une seconde vie à un canapé, un matelas ou une voiture.</p><p>C’est ce travail répété, intervention après intervention, qui a fini par construire une réputation : aujourd’hui, Keepnew affiche une note de <span class=\\"hl\\">4,9/5</span> sur plus de 110 avis Google. Être identifié parmi les 10 meilleurs dossiers indépendants du pays, c’est voir ce travail quotidien reconnu au-delà de notre région — et c’est un signal qui compte autant pour nous que pour nos clients.</p>"},{"type":"heading","level":"h2","text":"Ce que ce trophée récompense, concrètement"},{"type":"text","text":"<p>Un trophée ne se gagne jamais sur un dossier de candidature seul : il se construit sur des chiffres et des habitudes de travail. Voici, très concrètement, ce qui se trouve derrière notre sélection :</p><ul><li><strong>Plus de 400 canapés</strong> nettoyés en profondeur et remis en état, directement au domicile de nos clients.</li><li><strong>Plus de 250 voitures</strong> remises à neuf, intérieur comme extérieur.</li><li>Une <strong>note de 4,9/5</strong> sur plus de 110 avis Google, construite intervention après intervention.</li><li>Une intervention possible directement <strong>à domicile</strong>, dans toute la province de Liège, à Namur, à Bruxelles et dans le Luxembourg belge — sans que nos clients aient à se déplacer.</li><li>Des produits professionnels choisis pour leur efficacité et leur impact environnemental limité.</li></ul><p>Ce sont ces éléments-là, plus que n’importe quel argumentaire, qui ont fait la différence dans un concours qui recevait plus de 850 candidatures.</p>"},{"type":"quote","text":"Ce trophée, ce n’est pas la ligne d’arrivée. C’est la confirmation qu’on peut construire quelque chose de solide à Liège, avec nos méthodes, sans dénaturer ce qui a fait le succès de Keepnew depuis le premier canapé nettoyé.","author":"Antoine Forêt","role":"Co-fondateur de Keepnew"},{"type":"heading","level":"h2","text":"Pourquoi ce genre de reconnaissance compte pour une entreprise comme la nôtre"},{"type":"text","text":"<p>Une entreprise comme Keepnew ne dispose pas d’un budget de communication comparable à celui d’une grande enseigne. Notre visibilité se construit intervention après intervention : un canapé nettoyé chez vous, une voiture polie dans notre atelier, un avis laissé sur Google. C’est un travail lent, qui ne se voit pas toujours de l’extérieur.</p><p>Une sélection au niveau national, dans un concours qui recevait plus de 850 candidatures, change cette donne : elle place notre travail sous un regard que nous n’aurions pas atteint seuls. Pour une entreprise familiale liégeoise, c’est aussi une manière de montrer qu’un projet ancré localement — dans la province de Liège, à Visé, chez des clients de Namur, Bruxelles ou du Luxembourg belge — peut rivaliser à l’échelle du pays, sans quitter son territoire ni changer de méthode.</p>"},{"type":"heading","level":"h2","text":"La suite : un atelier, et encore un peu plus d’ambition"},{"type":"text","text":"<p>Cette sélection au Trophée de l’Indépendant est arrivée la même année que l’ouverture de notre <a href=\\"/blog/nouvel-atelier-keepnew-a-vise\\">nouvel atelier à Visé</a>, entièrement dédié aux véhicules — polissage professionnel multi-étapes et traitement céramique. Les deux nouvelles ne sont pas séparées : elles racontent la même trajectoire, celle d’une entreprise qui grandit sans s’éloigner de ce qui a fait sa réputation, le travail bien fait, chez vous ou dans notre atelier.</p>"},{"type":"heading","level":"h2","text":"Merci"},{"type":"text","text":"<p>Cette reconnaissance, nous la devons d’abord à nos clients — les plus de 110 personnes qui ont pris le temps de laisser un avis, et toutes celles qui nous ont fait confiance sans forcément l’écrire. C’est cette confiance, répétée des centaines de fois, qui a fait le dossier. Merci de continuer à nous l’accorder.</p>"},{"type":"accordion","h2":"Vos questions sur le Trophée de l’Indépendant","items":[{"q":"Qu’est-ce que le Trophée de l’Indépendant organisé par Orange ?","a":"C’est un concours national organisé par Orange Belgique, qui met en avant des entrepreneurs indépendants belges pour leur parcours, leur régularité et la qualité de leur travail. En 2024, plus de 850 entreprises y ont participé."},{"q":"Keepnew a-t-il remporté le Trophée de l’Indépendant 2024 ?","a":"Keepnew a été sélectionné parmi les 10 finalistes du concours, sur plus de 850 candidatures à l’échelle nationale — une distinction en tant que finaliste, et non le premier prix du concours."},{"q":"Où intervient Keepnew pour le nettoyage à domicile ?","a":"Keepnew intervient à domicile dans toute la province de Liège, à Namur, à Bruxelles et dans le Luxembourg belge, pour le nettoyage de canapés, matelas et voitures. Un atelier dédié aux véhicules est également ouvert à Visé."},{"q":"Comment réserver un nettoyage avec Keepnew ?","a":"La réservation se fait en ligne, en quelques minutes, avec un devis affiché avant de confirmer. Un lien de réservation est disponible en bas de cette page."}]},{"type":"cta-final","eyebrow":"RÉSERVATION EN LIGNE","title":"Prendre RDV en 2 min","bg":"blue"}]',
  'published',
  '2024-11-14 09:00:00',
  (SELECT id FROM kn_categories WHERE slug = 'actualites' AND lang = 'fr' LIMIT 1),
  NULL,
  'Keepnew finaliste du Trophée de l’Indépendant Orange 2024',
  'Keepnew, entreprise familiale liégeoise, sélectionnée parmi les 10 finalistes du Trophée de l’Indépendant Orange 2024, sur plus de 850 candidatures nationales.',
  NULL,
  '2024-11-14 09:00:00',
  '2024-11-14 09:00:00'
)
